<script setup>import {dateLabel} from '#shared/utils/format.js';defineProps({order:Object})</script><template><NuxtLink :to="'/therapist/jobs/'+order.id" class="panel job-card"><div class="dispatch-card-top"><span class="order-number">{{ order.orderNumber }}</span><UiBadge :status="order.assignment?.isActive?order.orderStatus:order.assignment?.responseStatus||order.orderStatus" /></div><div class="job-time"><UiIcon name="clock" :size="20" /><strong>{{ order.bookingTime.slice(0,5) }}</strong><span>{{ dateLabel(order.bookingDate) }}</span></div><h3>{{ order.items.map(i=>i.serviceNameSnapshot).join(', ') }}</h3><p>{{ order.items.reduce((n,i)=>n+i.durationMinutes*i.qty,0) }} menit · {{ order.customerName }}</p><div class="dispatch-address"><UiIcon name="locations" :size="17" /><span>{{ order.addressSnapshot }}</span></div><div class="job-card-action">{{ !order.assignment?.isActive?'Lihat histori job':order.orderStatus==='ASSIGNED_THERAPIST'?'Lihat & terima job':'Lanjutkan job' }}<UiIcon name="arrow" :size="18" /></div></NuxtLink></template>